(function(){
  var G=Arena.Game, W=G.world;
  G._running = true;                     // el arrastre necesita el bucle vivo
  window.__snap = function () {
    var p = W.getPlayer();
    return { yaw: p ? +p.yaw.toFixed(5) : null, cam: +G.renderer.camera.yaw.toFixed(5) };
  };
  window.__cmp = function (a, b, modo) {
    var V = Arena.Math.Vec3, fail = [];
    var dCuerpo = V.angleDelta(a.yaw, b.yaw);
    var dCam = V.angleDelta(a.cam, b.cam);
    if (Math.abs(dCam) < 0.05) fail.push('la cámara no llegó a girar: el arrastre no entró');
    if (modo === 'steer') {
      if (Math.abs(dCuerpo) < 0.05) fail.push('el botón izquierdo no giró el cuerpo');
      else if (Math.abs(dCuerpo - dCam) > 1e-3) {
        fail.push('cuerpo y cámara no van 1:1 — cuerpo ' + dCuerpo.toFixed(4) + ' vs cámara ' + dCam.toFixed(4));
      }
    } else {
      if (Math.abs(dCuerpo) > 1e-6) fail.push('la mirada libre giró el cuerpo ' + dCuerpo.toFixed(5));
    }
    return { assert: !fail.length, fail: fail,
             cuerpo: +dCuerpo.toFixed(4), camara: +dCam.toFixed(4) };
  };
  return 'listo';
})()
